#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""
Security Scan — Detects common security issues in code.

Usage:
    python3 security_scan.py [directory]
    python3 security_scan.py --help

Checks:
- Hardcoded secrets (API keys, tokens, passwords)
- Vulnerable dependency indicators
- SQL injection patterns
- Command injection patterns
- Path traversal patterns
- Insecure crypto usage
- Missing security headers

Stdlib-only — no external dependencies.
"""

import argparse
import json
import os
import re
import sys
from pathlib import Path
from typing import List, Dict, Tuple

CRITICAL = "Critical"
HIGH = "High"
MEDIUM = "Medium"
LOW = "Low"


class Finding:
    def __init__(self, severity: str, category: str, message: str,
                 file: str, line: int = 0, suggestion: str = ""):
        self.severity = severity
        self.category = category
        self.message = message
        self.file = file
        self.line = line
        self.suggestion = suggestion

    def to_dict(self) -> dict:
        return {
            "severity": self.severity,
            "category": self.category,
            "message": self.message,
            "file": self.file,
            "line": self.line,
            "suggestion": self.suggestion,
        }


# Secret patterns — regex + description
SECRET_PATTERNS = [
    (r'(?:api[_-]?key|apikey)\s*[:=]\s*["\'][a-zA-Z0-9_\-]{20,}["\']', "Hardcoded API key"),
    (r'(?:secret|password|passwd|pwd)\s*[:=]\s*["\'][^"\']{8,}["\']', "Hardcoded secret/password"),
    (r'(?:token|auth_token|access_token)\s*[:=]\s*["\'][a-zA-Z0-9_\-\.]{20,}["\']', "Hardcoded token"),
    (r'(?:aws_access_key_id|aws_secret_access_key)\s*[:=]\s*["\'][A-Za-z0-9/+=]{20,}["\']', "AWS credential"),
    (r'AKIA[0-9A-Z]{16}', "AWS Access Key ID"),
    (r'(?:sk|pk)[-_](?:live|test)[-_][a-zA-Z0-9]{20,}', "Stripe API key"),
    (r'ghp_[a-zA-Z0-9]{36}', "GitHub personal access token"),
    (r'-----BEGIN (?:RSA|DSA|EC|OPENSSH) PRIVATE KEY-----', "Private key"),
    (r'(?:mongodb|postgres|mysql|redis)://[^\s"\']+:[^\s"\']+@', "Database connection string with credentials"),
]

# Injection patterns
INJECTION_PATTERNS = [
    # SQL injection
    (r'(?:query|execute|raw)\s*\(\s*[`"\'].*\$\{', HIGH, "SQL Injection",
     "Potential SQL injection via string interpolation",
     "Use parameterized queries instead of string interpolation"),
    (r'(?:query|execute|raw)\s*\(\s*.*\+\s*(?:req\.|params\.|body\.)', HIGH, "SQL Injection",
     "Potential SQL injection via string concatenation",
     "Use parameterized queries instead of concatenation"),
    # Command injection
    (r'(?:exec|spawn|execSync|system|popen)\s*\(.*(?:req\.|params\.|body\.|user)', CRITICAL, "Command Injection",
     "Potential command injection from user input",
     "Validate and sanitize input, use allowlists, avoid shell commands with user input"),
    (r'child_process.*(?:req\.|params\.|body\.)', CRITICAL, "Command Injection",
     "child_process with user-controlled input",
     "Never pass user input to shell commands"),
    # Path traversal
    (r'(?:readFile|writeFile|createReadStream|open)\s*\(.*(?:req\.|params\.|body\.)', HIGH, "Path Traversal",
     "File operation with user-controlled path",
     "Validate and sanitize file paths, use path.resolve with a base directory"),
    (r'\.\./', MEDIUM, "Path Traversal",
     "Relative path traversal pattern in code",
     "Ensure path traversal sequences are sanitized"),
]

# Insecure patterns
INSECURE_PATTERNS = [
    (r'eval\s*\(', HIGH, "Code Injection", "eval() usage", "Avoid eval() — use safer alternatives"),
    (r'dangerouslySetInnerHTML', HIGH, "XSS", "dangerouslySetInnerHTML usage", "Sanitize HTML with DOMPurify before rendering"),
    (r'innerHTML\s*=', HIGH, "XSS", "innerHTML assignment", "Use textContent or sanitize HTML"),
    (r'document\.write\s*\(', MEDIUM, "XSS", "document.write usage", "Use DOM manipulation methods instead"),
    (r'(?:md5|sha1)\s*\(', MEDIUM, "Weak Crypto", "Weak hash algorithm", "Use SHA-256+ for hashing, bcrypt/argon2 for passwords"),
    (r'Math\.random\s*\(', LOW, "Weak Crypto", "Math.random for potentially security-sensitive use", "Use crypto.getRandomValues() for security-sensitive randomness"),
    (r'(?:http|ws)://', LOW, "Insecure Transport", "Non-HTTPS URL", "Use HTTPS/WSS for all connections"),
    (r'cors\s*\(\s*\)', MEDIUM, "CORS", "CORS with no origin restriction", "Configure CORS with specific allowed origins"),
    (r'Access-Control-Allow-Origin.*\*', MEDIUM, "CORS", "Wildcard CORS origin", "Restrict to specific trusted origins"),
    (r'localStorage\.setItem.*(?:token|jwt|session|auth)', HIGH, "Insecure Storage", "Sensitive token in localStorage", "Use httpOnly cookies for auth tokens"),
    (r'console\.log.*(?:password|secret|token|key|credential)', MEDIUM, "Info Leak", "Sensitive data in console.log", "Remove console.log of sensitive data before production"),
    (r'(?:disabled|no).*(?:csrf|xsrf)', HIGH, "CSRF", "CSRF protection disabled", "Enable CSRF protection"),
]

SKIP_DIRS = {'node_modules', '.next', 'dist', 'build', '.git', 'vendor', '__pycache__', '.venv', 'venv'}
SOURCE_EXTENSIONS = ('.ts', '.tsx', '.js', '.jsx', '.py', '.go', '.rs', '.rb', '.java', '.php', '.vue', '.svelte')


def find_files(directory: str) -> List[str]:
    """Find source files recursively."""
    files = []
    for root, dirs, filenames in os.walk(directory):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for f in filenames:
            if f.endswith(SOURCE_EXTENSIONS):
                files.append(os.path.join(root, f))
    return files


def check_secrets(content: str, filepath: str) -> List[Finding]:
    """Check for hardcoded secrets."""
    findings = []
    lines = content.split('\n')

    # Skip test files, example files, mock files
    basename = os.path.basename(filepath).lower()
    if any(x in basename for x in ['test', 'spec', 'mock', 'fixture', 'example', 'sample']):
        return findings

    for i, line in enumerate(lines, 1):
        # Skip comments
        stripped = line.strip()
        if stripped.startswith('//') or stripped.startswith('#') or stripped.startswith('*'):
            continue
        # Skip env variable references (these are fine)
        if re.search(r'process\.env\.|os\.environ|os\.getenv|env\(', line):
            continue

        for pattern, desc in SECRET_PATTERNS:
            if re.search(pattern, line, re.IGNORECASE):
                findings.append(Finding(
                    CRITICAL, "Secrets",
                    desc,
                    filepath, i,
                    "Move to environment variables or a secret manager"
                ))
                break  # One finding per line

    return findings


def check_injections(content: str, filepath: str) -> List[Finding]:
    """Check for injection vulnerabilities."""
    findings = []
    lines = content.split('\n')

    for i, line in enumerate(lines, 1):
        for pattern, severity, category, message, suggestion in INJECTION_PATTERNS:
            if re.search(pattern, line, re.IGNORECASE):
                findings.append(Finding(severity, category, message, filepath, i, suggestion))
                break

    return findings


def check_insecure_patterns(content: str, filepath: str) -> List[Finding]:
    """Check for insecure code patterns."""
    findings = []
    lines = content.split('\n')

    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        if stripped.startswith('//') or stripped.startswith('#'):
            continue

        for pattern, severity, category, message, suggestion in INSECURE_PATTERNS:
            if re.search(pattern, line, re.IGNORECASE):
                findings.append(Finding(severity, category, message, filepath, i, suggestion))

    return findings


def check_env_files(directory: str) -> List[Finding]:
    """Check for committed .env files."""
    findings = []
    env_files = ['.env', '.env.local', '.env.production', '.env.development']

    for env_file in env_files:
        filepath = os.path.join(directory, env_file)
        if os.path.exists(filepath):
            # Check if it's in .gitignore
            gitignore_path = os.path.join(directory, '.gitignore')
            in_gitignore = False
            if os.path.exists(gitignore_path):
                try:
                    with open(gitignore_path) as f:
                        for line in f:
                            if env_file in line.strip():
                                in_gitignore = True
                                break
                except IOError:
                    pass

            if not in_gitignore:
                findings.append(Finding(
                    CRITICAL, "Secrets",
                    f"{env_file} exists and may not be in .gitignore",
                    filepath, 0,
                    f"Add {env_file} to .gitignore immediately"
                ))

    return findings


def run_scan(directory: str) -> Tuple[List[Finding], dict]:
    """Run all security checks."""
    all_findings: List[Finding] = []
    files = find_files(directory)

    if not files:
        print(f"No source files found in {directory}", file=sys.stderr)
        sys.exit(1)

    for filepath in files:
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
        except (IOError, OSError):
            continue

        all_findings.extend(check_secrets(content, filepath))
        all_findings.extend(check_injections(content, filepath))
        all_findings.extend(check_insecure_patterns(content, filepath))

    all_findings.extend(check_env_files(directory))

    summary = {
        "files_scanned": len(files),
        "total_findings": len(all_findings),
        "by_severity": {},
        "by_category": {},
    }

    for sev in [CRITICAL, HIGH, MEDIUM, LOW]:
        count = sum(1 for f in all_findings if f.severity == sev)
        if count:
            summary["by_severity"][sev] = count

    for f in all_findings:
        summary["by_category"][f.category] = summary["by_category"].get(f.category, 0) + 1

    return all_findings, summary


def main():
    parser = argparse.ArgumentParser(
        description="Security Scan — Detect common security issues in code"
    )
    parser.add_argument("directory", nargs="?", default=".",
                       help="Directory to scan (default: current directory)")
    parser.add_argument("--format", choices=["text", "json"], default="text",
                       help="Output format")

    args = parser.parse_args()
    directory = os.path.abspath(args.directory)

    if not os.path.isdir(directory):
        print(f"Error: {directory} is not a directory", file=sys.stderr)
        sys.exit(1)

    findings, summary = run_scan(directory)

    if args.format == "json":
        output = {
            "summary": summary,
            "findings": [f.to_dict() for f in findings],
        }
        print(json.dumps(output, indent=2))
    else:
        print("━" * 60)
        print("  SECURITY SCAN REPORT")
        print("━" * 60)
        print(f"\n  Files scanned: {summary['files_scanned']}")
        print(f"  Total findings: {summary['total_findings']}\n")

        if summary["by_severity"]:
            for sev, count in summary["by_severity"].items():
                print(f"  {sev}: {count}")

        severity_order = {CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3}
        sorted_findings = sorted(findings, key=lambda f: severity_order.get(f.severity, 4))

        current_severity = None
        for f in sorted_findings:
            if f.severity != current_severity:
                current_severity = f.severity
                print(f"\n  [{current_severity}]")
                print("  " + "─" * 40)
            loc = f"{f.file}:{f.line}" if f.line else f.file
            print(f"\n  {f.category}: {f.message}")
            print(f"  Location: {loc}")
            if f.suggestion:
                print(f"  Fix: {f.suggestion}")

        print("\n" + "━" * 60)

    critical_count = summary["by_severity"].get(CRITICAL, 0)
    sys.exit(1 if critical_count > 0 else 0)


if __name__ == "__main__":
    main()
